async def act(page):
    """
    Add a simple product named 'Lelelumon Yoga Mat' with 42 in stock,
    size 'uni-size', color 'black', priced at $769.99.

    Approach:
    - Use a relative goto directly to the Add New Product page to avoid brittle menu interactions.
