async def act(page):
    """
    Add a simple product named 'Lelelumon Yoga Mat' with 42 in stock,
    size 'uni-size', color 'black', priced at $769.99.

    Approach:
    - Use a relative goto directly to the Add New Product page to avoid brittle menu interactions.
    - Use only get_by_role / select_option APIs per guidance.
    - Make Save the final action (it will navigate away / commit the product).
    """
    import asyncio

    # No knowledge_base functions are available in the provided environment, so none are used.

    # Navigate directly to the Add New Product page using a relative URL.
    # This keeps us from needing to click the top-level Catalog menu and then Manage Products.
    await page.goto('/index.php/admin/catalog_product/new/')
    await page.wait_for_load_state('networkidle')

    # Fill product name
    try:
        await page.get_by_role("textbox", name="Name").fill("Lelelumon Yoga Mat")
    except Exception:
        # fallback: try the first textbox
        try:
            await page.get_by_role("textbox").nth(0).fill("Lelelumon Yoga Mat")
        except Exception:
            pass

    # Fill price
    try:
        await page.get_by_role("textbox", name="Price").fill("769.99")
    except Exception:
        try:
            await page.get_by_role("textbox", name="Product Price").fill("769.99")
        except Exception:
            try:
                await page.get_by_role("textbox").nth(1).fill("769.99")
            except Exception:
                pass

    # Try to set Size attribute (combobox)
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="uni-size")
    except Exception:
        # try some common variants
        for alt in ("Uni-size", "uni size", "uni-size ", "uniSize"):
            try:
                await page.get_by_role("combobox", name="Size").select_option(label=alt)
                break
            except Exception:
                continue

    # Try to set Color attribute (combobox)
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="black")
    except Exception:
        try:
            await page.get_by_role("combobox", name="Colour").select_option(label="black")
        except Exception:
            try:
                await page.get_by_role("combobox", name="Color").select_option(label="Black")
            except Exception:
                pass

    # Open Inventory tab/section to set quantity and stock
    try:
        await page.get_by_role("tab", name="Inventory").click()
        # allow any inventory panel to load
        await asyncio.sleep(0.5)
    except Exception:
        # fallback to link or button
        try:
            await page.get_by_role("link", name="Inventory").click()
            await asyncio.sleep(0.5)
        except Exception:
            try:
                await page.get_by_role("button", name="Inventory").click()
                await asyncio.sleep(0.5)
            except Exception:
                pass

    # Set quantity (Qty)
    try:
        await page.get_by_role("textbox", name="Qty").fill("42")
    except Exception:
        try:
            await page.get_by_role("textbox", name="Quantity").fill("42")
        except Exception:
            try:
                # sometimes qty is third textbox
                await page.get_by_role("textbox").nth(2).fill("42")
            except Exception:
                pass

    # Set stock availability to In Stock
    try:
        await page.get_by_role("combobox", name="Stock Availability").select_option(label="In Stock")
    except Exception:
        try:
            await page.get_by_role("combobox", name="Stock").select_option(label="In Stock")
        except Exception:
            try:
                await page.get_by_role("combobox", name="Stock Status").select_option(label="In Stock")
            except Exception:
                pass

    # Final action: Save the product. Use a parent group to avoid ambiguous matches.
    save_clicked = False
    parent_candidates = [
        page.get_by_role("group", name="Page Actions"),
        page.get_by_role("group", name="Actions"),
        page.get_by_role("toolbar"),
        page.get_by_role("banner"),
    ]
    for parent in parent_candidates:
        try:
            await parent.wait_for(timeout=1500)
            await parent.get_by_role("button", name="Save").click()
            save_clicked = True
            break
        except Exception:
            continue

    if not save_clicked:
        try:
            await page.get_by_role("button", name="Save").click()
            save_clicked = True
        except Exception:
            # give a brief pause to let UI settle; cannot do more reliably
            await asyncio.sleep(1)

    # Let navigation / save complete
    try:
        await page.wait_for_load_state('networkidle')
    except Exception:
        await asyncio.sleep(1)
